      let bottom;
      try { bottom = child.y + child.height; } catch (e) { continue; }
      if (typeof bottom !== 'number' || !isFinite(bottom)) continue;
      if (bottom + HOST_GUTTER > nextY) nextY = bottom + HOST_GUTTER;
