  set.setSharedPluginData('ds_contracts', 'statePreviewAxis',
    C.statePreviewAxis ? JSON.stringify(C.statePreviewAxis) : '');
  set.setSharedPluginData('ds_contracts', 'semantics',
    C.semantics ? JSON.stringify(C.semantics) : '');
